//! RICH TEXT
import 'package:flutter_quill/flutter_quill.dart' as quill;
import 'package:flutter_localizations/flutter_localizations.dart';

// MATERIAL APP LOCALIZATION
MaterialApp(
  localizationsDelegates: const [
    GlobalMaterialLocalizations.delegate,
    GlobalCupertinoLocalizations.delegate,
    GlobalWidgetsLocalizations.delegate,
    FlutterQuillLocalizations.delegate,
  ],
);

// CONTROLLER
final quill.QuillController controller = quill.QuillController.basic();

// TOOLBAR
quill.QuillSimpleToolbar(
  controller: controller,
  config: const quill.QuillSimpleToolbarConfig(),
);

// EDITOR
quill.QuillEditor.basic(
  controller: controller,
  config: const quill.QuillEditorConfig(),
);

// DISPOSE
@override
void dispose() {
  controller.dispose();
  super.dispose();
}

// ANDROID MANIFEST
// android/app/src/main/AndroidManifest.xml

<provider
  android:name="androidx.core.content.FileProvider"
  android:authorities="${applicationId}.fileprovider"
  android:exported="false"
  android:grantUriPermissions="true">

  <meta-data
    android:name="android.support.FILE_PROVIDER_PATHS"
    android:resource="@xml/file_paths" />

</provider>

// FILE PATHS
// android/app/src/main/res/xml/file_paths.xml

<paths>
  <cache-path name="cache" path="." />
</paths>

class FormStyle {
  static const Color primary = Colors.blueAccent;
  static const Color error = Colors.red;
  static const double baseRadius = 8.0;
  static const double formHeight = 56.0;
  static const double fontSize = 15.0;
}

final form = FormHelperController();

@override
void initState() {
  super.initState();

  final amountNode = form.node('amount', initialValue: '10000');

  // Smart Event Listener: Memantau event dengan context passing
  amountNode.addListener((node) {
    if (node.hasFocus) {
      print('Field fokus! Teks saat ini: ${node.text}');
    } else {
      // Contoh logic ketika kehilangan fokus
      if (node.text.isEmpty) {
        node.shake(); // getarkan jika kosong
      }
    }
  });

  // Smart Event Listener: Memantau perubahan teks realtime
  amountNode.addTextListener((text) {
    print('Nilai amount berubah menjadi: $text');
  });

  // Contoh penggunaan method lain
  amountNode.disable();
}

@override
void dispose() {
  // Cukup panggil form.dispose(). Seluruh node, Controller, FocusNode,
  // beserta anonymous function (listeners) di atas akan disapu bersih otomatis.
  form.dispose();
  super.dispose();
}

final _formCtrl = FormHelperController(
 shakeOnError: true,
);

/// set nested object
_formCtrl.set('profile', {
 'name': 'Affan',
 'email': 'affan@gmail.com',
});

/// append list item
_formCtrl.append('tags', 'Flutter');

/// append object into array
_formCtrl.append('tiers', {
 'min': '10000',
 'disc': '5',
});

/// access node
final emailNode = _formCtrl.node('profile.email');

/// trigger shake animation manually
emailNode.shake();

/// focus node
emailNode.focus();

/// serialize payload
final payload = _formCtrl.getAllValues().toMap();

FormHelperWidget.Status(
  controller: _formCtrl,
  builder: (isValid) {
    return ElevatedButton(
      onPressed: isValid
          ? () {
              debugPrint('Form valid!');
            }
          : null,
      child: Text(
        isValid ? 'Simpan Data' : 'Lengkapi Form',
      ),
    );
  },
)

FormHelperWidget.Otp(
  label: 'Kode OTP',
  digitInfoText: 'Masukkan 6 digit kode verifikasi',
  node: _formCtrl.node('otp'),
  length: 6,
  onlyNumber: true,
  obscureText: false,
  prefix: Icon(Icons.lock_outline),
