FormHelperWidget.RichText(
  label: 'Isi Artikel',
  node: _formCtrl.node('artikel'),
  theme: FormRichTextTheme.document,
  outputFormat: FormRichTextOutput.delta,
  minHeight: 280,
  maxHeight: 500,
  showPreview: true,
  compactToolbar: false,
  validator: (val) {
    if (val.trim().isEmpty) {
      return 'Artikel wajib diisi';
    }
    return null;
  },
)

FormHelperWidget.Date(
  label: 'Tanggal Lahir',
  node: _formCtrl.node('dob'),
  firstDate: DateTime(1950),
  lastDate: DateTime.now(),
  displayBuilder: (rawDate) {
    if (rawDate.isEmpty) return '';
    try {
      DateTime parsed = DateTime.parse(rawDate);
      return DateFormat('dd MMMM yyyy', 'id_ID').format(parsed);
    } catch(e) { return rawDate; }
  },
)

FormHelperWidget.Time(
  label: 'Jam Buka',
  node: _formCtrl.node('open_time'),
  displayBuilder: (raw) {
    if (raw.isEmpty) return '';
    final parts = raw.split(':');
    int hour = int.parse(parts[0]);
    String ampm = hour >= 12 ? 'PM' : 'AM';
    hour = hour % 12 == 0 ? 12 : hour % 12;
    return '${hour.toString().padLeft(2, "0")}:${parts[1]} $ampm';
  },
)

FormHelperWidget.RangeTime(
  label: 'Jam Operasional',
  node: _formCtrl.node('operational_hours'),
  direction: FormLayoutDirection.adaptive,
  displayBuilder: (raw) {
    if (raw.isEmpty) return '';
    final parts = raw.split(' - ');
    return parts[0].substring(0, 5) + ' s/d ' + parts[1].substring(0, 5);
  },
)

FormHelperWidget.RangeDate(
  label: 'Filter Periode',
  node: _formCtrl.node('periode'),
  displayBuilder: (raw) {
    if (raw.isEmpty) return '';
    final parts = raw.split(' - ');
    if (parts.length != 2) return raw;
    final start = DateTime.parse(parts[0].split(' ')[0]);
    final end = DateTime.parse(parts[1].split(' ')[0]);
    return DateFormat('dd MMM').format(start) + ' - ' + DateFormat('dd MMM yyyy').format(end);
  },
)

